::: {.cell}

```{.r .cell-code .hidden}
#| label: replication-pwr-decisions
# The decisions of the replication, one row per look and combination of test
# results; "pass" means that the one-sided test rejects no blocking at the
# threshold of the look
decisions <- tibble::tribble(
  ~look, ~bi2,   ~bi3,    ~replication, ~next_step,      ~note,
  1L,    "pass", "pass",  "SUCCESS",    "-03 with BI3",  "no top-up",
  1L,    "pass", "fail",  "SUCCESS",    "-03 with BI2",  "no top-up",
  1L,    "fail", "pass",  "FAILURE",    "-03 with BI3",  "no top-up",
  1L,    "fail", "fail",  "Undecided",  "Look 2",        "top-up of the sample",
  2L,    "pass", "pass",  "SUCCESS",    "-03 with BI3",  NA,
  2L,    "pass", "fail",  "SUCCESS",    "-03 with BI2",  "theorise why BI2 was the more sensitive index",
  2L,    "fail", "pass",  "FAILURE",    "-03 with BI3",  NA,
  2L,    "fail", "fail",  "FAILURE",    "Change course", "no -03 extension"
)

# Thresholds and sample sizes of the looks at the assumed retention, as printed
thresholds <- c(
  paste("<", sub("^0", "", sprintf("%.3f", alpha1))),
  paste("<", sub("^0", "", sprintf("%.3f", planned$p2)))
)
look_labels <- c(
  sprintf("Look 1\nn ≥ %d\np %s", n1_min, thresholds[1L]),
  sprintf("Look 2\nn ≈ %d\np %s", planned$n2, thresholds[2L])
)
```
